import { Group, Mesh, PlaneGeometry, MeshPhysicalNodeMaterial, Color, FrontSide } from 'three/webgpu';
import { uv, mix } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const cleanups = [];
  const cards = [];

  // Design constants
  const cardWidth = 1.6;
  const cardHeight = 1.0;
  const stripRotationY = -18 * Math.PI / 180;
  const cardPositions = [-3.7, -1.85, 0, 1.85, 3.7];

  // Create backdrop with gradient
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropUV = uv();
  const gradientNode = mix(
    new Color('#0b0b10'),
    new Color('#12121a'),
    backdropUV.y
  );
  const backdropMat = new MeshPhysicalNodeMaterial({
    colorNode: gradientNode,
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // Create 5 cards
  for (let i = 0; i < 5; i++) {
    const cardGeo = new PlaneGeometry(cardWidth, cardHeight);
    const cardMat = new MeshPhysicalNodeMaterial({
      color: new Color('#e8ecf2'),
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
      side: FrontSide,
      transparent: true,
      opacity: i === 2 ? 1.0 : 0.55,
    });

    const card = new Mesh(cardGeo, cardMat);
    card.position.x = cardPositions[i];
    card.userData.cardIndex = i;
    card.scale.set(i === 2 ? 1.0 : 0.92, i === 2 ? 1.0 : 0.92, 1);

    // Counter-rotate focused card to face camera
    if (i === 2) {
      card.rotation.y = -stripRotationY;
    }

    cards.push(card);
    group.add(card);

    // Add bevel frame
    const bevelGeo = new PlaneGeometry(cardWidth + 0.05, cardHeight + 0.05);
    const bevelMat = new MeshPhysicalNodeMaterial({
      color: new Color('#16161d'),
    });
    const bevel = new Mesh(bevelGeo, bevelMat);
    bevel.position.z = -0.0005;
    card.add(bevel);
  }

  // Load and apply texture to cards
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    cards.forEach((card) => {
      card.material.map = tex;
      card.material.needsUpdate = true;
    });
  });

  // Rotate entire filmstrip for perspective recession
  group.rotation.y = stripRotationY;

  // Add headline text
  const headlineText = ctx.fontAtlas.createText('The collection', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'left',
  });
  headlineText.position.set(-2.6, 1.5, 0);
  group.add(headlineText);

  // Add body text
  const bodyText = ctx.fontAtlas.createText('Five calibres. One discipline.', {
    fontSize: 26,
    color: '#e8ecf2',
    align: 'left',
  });
  bodyText.position.set(-2.6, -1.5, 0);
  group.add(bodyText);

  // Add card captions
  const captions = ['NA-01 MERIDIAN', 'NA-02 NOCTURNE', 'NA-03 SIGNAL', 'NA-04 VANTAGE', 'NA-05 ARCHIVE'];
  captions.forEach((caption, i) => {
    const captionText = ctx.fontAtlas.createText(caption, {
      fontSize: 18,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: 1.0,
    });
    captionText.position.set(cardPositions[i], -cardHeight / 2 - 0.4, 0);
    group.add(captionText);
  });

  // Apply parallax-scroll primitive with intensity 0.5
  const scrollResult = ctx.primitives['parallax-scroll'](group, { intensity: 0.5 });
  if (scrollResult?.cleanup) {
    cleanups.push(scrollResult.cleanup);
  }

  // Add accent underline bar to focused card
  const underlineGeo = new PlaneGeometry(1.6, 0.035);
  const underlineMat = new MeshPhysicalNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.3,
  });
  const underline = new Mesh(underlineGeo, underlineMat);
  underline.position.y = -cardHeight / 2 - 0.08;
  underline.position.z = 0.01;
  cards[2].add(underline);

  // Cleanup function
  group.userData.cleanup = () => {
    cleanups.forEach(fn => {
      if (typeof fn === 'function') fn();
    });
    gsap.killTweensOf(cards);
    gsap.killTweensOf(group);

    group.traverse(obj => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach(m => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });
  };

  return group;
}
